package com.coworkhub.security;
import io.jsonwebtoken.*;import io.jsonwebtoken.security.Keys;import org.springframework.stereotype.Service;import org.springframework.beans.factory.annotation.Value;import java.time.*;import java.util.*;import javax.crypto.SecretKey;import java.nio.charset.StandardCharsets;
@Service public class JwtService {private final SecretKey key;private final Clock clock;public JwtService(@Value("${jwt.secret:CoWorkHubDevelopmentKeyForJWTSigningOnlyChangeInProduction123456789}") String secret,Clock clock){key=Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));this.clock=clock;}public String generate(String username,String role,Long memberId){return Jwts.builder().subject(username).claim("role",role).claim("memberId",memberId).issuedAt(Date.from(clock.instant())).expiration(Date.from(clock.instant().plus(Duration.ofMinutes(60)))).signWith(key).compact();}public Claims parse(String token){return Jwts.parser().verifyWith(key).build().parseSignedClaims(token).getPayload();}}
